"use client"

import type { ExtraAction } from "@/components/data-table/core/types"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import type { Row } from "@tanstack/react-table"
import { MoreHorizontal, Pencil, Trash2 } from "lucide-react"

interface DataTableRowActionsProps<TData> {
  row: Row<TData>
  onEdit?: (row: Row<TData>) => void
  onDelete?: (row: Row<TData>) => void
  extraActions?: ExtraAction<TData>[]
  disabled?: boolean
  disabledEdit?: boolean
  disabledDelete?: boolean
}

export function DataTableRowActions<TData>({
  row,
  onEdit,
  onDelete,
  extraActions,
  disabled,
  disabledEdit,
  disabledDelete,
}: DataTableRowActionsProps<TData>) {
  const hasExtras = extraActions && extraActions.length > 0

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild disabled={disabled}>
        <Button variant="ghost" size="icon" className="size-8 p-0 data-[state=open]:bg-muted">
          <MoreHorizontal className="size-4" />
          <span className="sr-only">Open row actions</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-40">
        {onEdit && (
          <DropdownMenuItem onClick={() => onEdit(row)} disabled={disabledEdit}>
            <Pencil className="size-3.5 text-muted-foreground" />
            Edit
          </DropdownMenuItem>
        )}
        {onDelete && (
          <DropdownMenuItem
            onClick={() => onDelete(row)}
            disabled={disabledDelete}
            className="text-destructive focus:text-destructive"
          >
            <Trash2 className="size-3.5" />
            Delete
          </DropdownMenuItem>
        )}
        {(onEdit || onDelete) && hasExtras && <DropdownMenuSeparator />}
        {hasExtras &&
          extraActions.map((action) => (
            <DropdownMenuItem
              key={action.label}
              onClick={() => action.onClick(row)}
              className={action.destructive ? "text-destructive focus:text-destructive" : undefined}
              disabled={action.disabled}
            >
              {action.icon && <span className="size-3.5 text-muted-foreground">{action.icon}</span>}
              {action.label}
            </DropdownMenuItem>
          ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

"use client"
import type { DataTableDensity } from "@/components/data-table/core/types"
import type { Table } from "@tanstack/react-table"
import { createContext, useContext } from "react"

export interface DataTableContextValue<TData = unknown> {
  table: Table<TData>
  density: DataTableDensity
  setDensity: (d: DataTableDensity) => void
}

export const DataTableContext = createContext<DataTableContextValue<unknown> | null>(null)

export function useDataTableContext<TData = unknown>(): DataTableContextValue<TData> {
  const ctx = useContext(DataTableContext)
  if (!ctx) throw new Error("useDataTableContext must be used within <DataTable>")
  return ctx as DataTableContextValue<TData>
}

"use client"

import { DataTableContext, useDataTableContext } from "@/components/data-table/core/context"
import type { DataTableContentProps, DataTableDensity } from "@/components/data-table/core/types"
import { DataTableSubRow } from "@/components/data-table/features/row-expansion"
import { DataTableEmptyState } from "@/components/data-table/features/states/empty"
import { DataTableLoadingState } from "@/components/data-table/features/states/loading"
import { densityRowClass } from "@/components/data-table/features/toolbar/density-toggle"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"
import { flexRender, type Table as TanStackTable } from "@tanstack/react-table"
import { Fragment, useState } from "react"

interface DataTableProps<TData> {
  table: TanStackTable<TData>
  className?: string
  children: React.ReactNode
}

export function DataTable<TData>({ table, className, children }: DataTableProps<TData>) {
  "use no memo"
  // TanStack Table exposes a stable mutable table instance; compiler memoization can hide table state updates.
  const [density, setDensity] = useState<DataTableDensity>("default")

  return (
    <DataTableContext.Provider
      value={{
        table: table as unknown as TanStackTable<unknown>,
        density,
        setDensity,
      }}
    >
      <div className={cn("relative space-y-3", className)}>{children}</div>
    </DataTableContext.Provider>
  )
}

export function DataTableContent({
  isLoading = false,
  loadingRowCount = 5,
  emptyState,
  onRowClick,
  renderSubRow,
}: DataTableContentProps) {
  "use no memo"
  // TanStack Table exposes a stable mutable table instance; compiler memoization can hide table state updates.
  const { table, density } = useDataTableContext()
  const hasRows = table.getRowModel().rows.length > 0
  const colCount = table.getVisibleLeafColumns().length

  const getPinClass = (pinned: "left" | "right" | false) => {
    if (pinned === "left") return "sticky left-0 z-10 bg-background"
    if (pinned === "right") return "sticky right-0 z-10 bg-background"
    return undefined
  }

  return (
    <div
      className={cn("overflow-x-auto rounded-md border border-border", densityRowClass[density])}
    >
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id} className="hover:bg-transparent">
              {headerGroup.headers.map((header) => (
                <TableHead
                  key={header.id}
                  colSpan={header.colSpan}
                  className={getPinClass(header.column.getIsPinned())}
                >
                  {header.isPlaceholder
                    ? null
                    : flexRender(header.column.columnDef.header, header.getContext())}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {isLoading ? (
            <DataTableLoadingState columns={colCount} rows={loadingRowCount} />
          ) : hasRows ? (
            table.getRowModel().rows.map((row) => (
              <Fragment key={row.id}>
                <TableRow
                  data-state={row.getIsSelected() ? "selected" : undefined}
                  onClick={
                    onRowClick
                      ? () => onRowClick(row as Parameters<typeof onRowClick>[0])
                      : undefined
                  }
                  className={onRowClick ? "cursor-pointer" : undefined}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className={getPinClass(cell.column.getIsPinned())}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
                {renderSubRow && (
                  <DataTableSubRow
                    row={row as Parameters<typeof renderSubRow>[0]}
                    colSpan={colCount}
                    renderSubRow={
                      renderSubRow as Parameters<typeof DataTableSubRow>[0]["renderSubRow"]
                    }
                  />
                )}
              </Fragment>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={colCount} className="p-0">
                {emptyState ?? <DataTableEmptyState />}
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}

"use client"

import { useDataTableContext } from "@/components/data-table/core/context"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { PanelLeft, PanelRight, Pin, Settings2 } from "lucide-react"

interface DataTableColumnToggleProps {
  enablePinning?: boolean
}

export function DataTableColumnToggle({ enablePinning = false }: DataTableColumnToggleProps) {
  "use no memo"
  const { table } = useDataTableContext()

  const columns = table
    .getAllLeafColumns()
    .filter((col) => {
      const meta = col.columnDef.meta as { isUtilityColumn?: boolean } | undefined
      return !meta?.isUtilityColumn
    })

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="ml-auto hidden h-8 lg:flex">
          <Settings2 />
          View
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-fit">
        <DropdownMenuLabel>Toggle columns</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {columns
          .filter((col) => col.getCanHide())
          .map((col) => (
            <DropdownMenuCheckboxItem
              key={col.id}
              className="capitalize"
              checked={col.getIsVisible()}
              onCheckedChange={(value) => col.toggleVisibility(!!value)}
            >
              {col.id?.replaceAll("_", " ").replaceAll("-", " ")}
            </DropdownMenuCheckboxItem>
          ))}
        {enablePinning && columns.some((col) => col.getCanPin()) && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuLabel>Pin columns</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {columns
              .filter((col) => col.getCanPin())
              .map((col) => {
                const pinned = col.getIsPinned()
                return (
                  <DropdownMenuItem key={col.id} className="flex items-center justify-between gap-4 capitalize">
                    <span>{col.id?.replaceAll("_", " ").replaceAll("-", " ")}</span>
                    <span className="flex items-center gap-1">
                      <button
                        aria-label={`Pin ${col.id} left`}
                        className={pinned === "left" ? "text-primary" : "text-muted-foreground"}
                        onClick={() => col.pin(pinned === "left" ? false : "left")}
                      >
                        <PanelLeft className="size-3.5" />
                      </button>
                      <button
                        aria-label={`Pin ${col.id} right`}
                        className={pinned === "right" ? "text-primary" : "text-muted-foreground"}
                        onClick={() => col.pin(pinned === "right" ? false : "right")}
                      >
                        <PanelRight className="size-3.5" />
                      </button>
                      {pinned && (
                        <button aria-label={`Unpin ${col.id}`} onClick={() => col.pin(false)}>
                          <Pin className="size-3.5 text-muted-foreground" />
                        </button>
                      )}
                    </span>
                  </DropdownMenuItem>
                )
              })}
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

"use client"

import { useDataTableContext } from "@/components/data-table/core/context"
import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from "lucide-react"

const DEFAULT_PAGE_SIZE_OPTIONS = [10, 20, 30, 50]

interface DataTablePaginationProps {
  pageSizeOptions?: number[]
  showRowSelectionCount?: boolean
  showPageSizeSelector?: boolean
}

export function DataTablePagination({
  pageSizeOptions = DEFAULT_PAGE_SIZE_OPTIONS,
  showRowSelectionCount = false,
  showPageSizeSelector = true,
}: DataTablePaginationProps) {
  "use no memo"
  // TanStack Table exposes a stable mutable table instance; compiler memoization can hide table state updates.
  const { table } = useDataTableContext()
  const pagination = table.getState().pagination
  const selectedCount = table.getFilteredSelectedRowModel().rows.length
  const totalCount = table.getRowCount()
  const pageCount = Math.max(table.getPageCount(), 1)
  const currentPage = Math.min(pagination.pageIndex + 1, pageCount)

  return (
    <div className="flex items-center justify-between px-2">
      <div className="flex-1 text-sm text-muted-foreground">
        {showRowSelectionCount ? (
          <span>
            {selectedCount} of {totalCount} row(s) selected
          </span>
        ) : null}
      </div>
      <div className="flex items-center space-x-6 lg:space-x-8">
        {showPageSizeSelector ? (
          <div className="flex items-center space-x-2">
            <p className="text-sm font-medium">Rows per page</p>
            <Select
              value={String(pagination.pageSize)}
              onValueChange={(value) => table.setPageSize(Number(value))}
            >
              <SelectTrigger className="h-8 w-[70px]">
                <SelectValue placeholder={pagination.pageSize} />
              </SelectTrigger>
              <SelectContent side="top">
                {pageSizeOptions.map((size) => (
                  <SelectItem key={size} value={`${size}`}>
                    {size}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        ) : null}
        <div className="flex w-[100px] items-center justify-center text-sm font-medium">
          Page {currentPage} of {pageCount}
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant="outline"
            size="icon"
            className="hidden size-8 lg:flex"
            onClick={() => table.setPageIndex(0)}
            disabled={!table.getCanPreviousPage()}
          >
            <span className="sr-only">Go to first page</span>
            <ChevronsLeft />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            <span className="sr-only">Go to previous page</span>
            <ChevronLeft />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="size-8"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            <span className="sr-only">Go to next page</span>
            <ChevronRight />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="hidden size-8 lg:flex"
            onClick={() => table.setPageIndex(Math.max(table.getPageCount() - 1, 0))}
            disabled={!table.getCanNextPage()}
          >
            <span className="sr-only">Go to last page</span>
            <ChevronsRight />
          </Button>
        </div>
      </div>
    </div>
  )
}

"use client"

import { Checkbox } from "@/components/ui/checkbox"
import type { ColumnDef } from "@tanstack/react-table"

export function rowSelectionColumn<TData>(): ColumnDef<TData> {
  return {
    id: "select",
    header: ({ table }) => (
      <Checkbox
        checked={
          table.getIsAllPageRowsSelected()
            ? true
            : table.getIsSomePageRowsSelected()
              ? "indeterminate"
              : false
        }
        onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
        aria-label="Select all"
        className="translate-y-[2px]"
      />
    ),
    cell: ({ row }) => {
      return (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(value) => {
            row.toggleSelected(!!value)
          }}
          aria-label="Select row"
          className="translate-y-[2px]"
        />
      )
    },
    enableSorting: false,
    enableHiding: false,
    meta: {
      isUtilityColumn: true,
    },
    size: 40,
  }
}

import { Empty, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty"
import { TableCell, TableRow } from "@/components/ui/table"
import { Database } from "lucide-react"

interface DataTableEmptyStateProps {
  title?: string
  description?: string
  colSpan?: number
}

export function DataTableEmptyState({
  title = "No results",
  description = "No data matches your current filters.",
}: DataTableEmptyStateProps) {
  return (
    <Empty className="border-0 py-16">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <Database />
        </EmptyMedia>
        <EmptyTitle>{title}</EmptyTitle>
        <EmptyDescription>{description}</EmptyDescription>
      </EmptyHeader>
    </Empty>
  )
}

export function DataTableEmptyRow({
  colSpan,
  children,
}: {
  colSpan: number
  children?: React.ReactNode
}) {
  return (
    <TableRow>
      <TableCell colSpan={colSpan} className="p-0">
        {children ?? <DataTableEmptyState />}
      </TableCell>
    </TableRow>
  )
}

import { Skeleton } from "@/components/ui/skeleton"
import { TableCell, TableRow } from "@/components/ui/table"

interface DataTableLoadingStateProps {
  columns: number
  rows?: number
}

export function DataTableLoadingState({ columns, rows = 5 }: DataTableLoadingStateProps) {
  return (
    <>
      {Array.from({ length: rows }).map((_, rowIndex) => (
        <TableRow key={rowIndex} className="hover:bg-transparent">
          {Array.from({ length: columns }).map((_, colIndex) => (
            <TableCell key={colIndex}>
              <Skeleton className="h-4 w-full" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  )
}

