"use client"

import { useDataTableContext } from "@/components/data-table/core/context"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import { Search, X } from "lucide-react"

interface DataTableSearchProps {
  placeholder?: string
}

export function DataTableSearch({ placeholder = "Search..." }: DataTableSearchProps) {
  "use no memo"
  // TanStack Table exposes a stable mutable table instance; compiler memoization can hide table state updates.
  const { table } = useDataTableContext()
  const value = (table.getState().globalFilter as string) ?? ""

  return (
    <InputGroup className="relative w-full lg:max-w-2xs">
      <InputGroupAddon>
        <Search className="text-muted-foreground" />
      </InputGroupAddon>
      <InputGroupInput
        placeholder={placeholder}
        value={value}
        onChange={(e) => table.setGlobalFilter(e.target.value)}
        className="h-8 pl-8"
      />
      <InputGroupAddon align="inline-end">
        {value && (
          <InputGroupButton onClick={() => table.setGlobalFilter("")}>
            <X />
          </InputGroupButton>
        )}
      </InputGroupAddon>
    </InputGroup>
  )
}

"use client"

import { useDataTableContext } from "@/components/data-table/core/context"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { ChevronDown } from "lucide-react"

type FilterOption = { label: string; value: string }

type DataTableStatusFilterProps<M extends "single" | "multi"> = {
  columnId: string
  mode: M
  options: FilterOption[]
  label?: string
  placeholder?: string
  allLabel?: string
} & (M extends "single"
  ? { value: string | undefined; onChange: (value: string | undefined) => void }
  : { value: string[]; onChange: (value: string[]) => void })

export function DataTableStatusFilter<M extends "single" | "multi">({
  columnId,
  mode,
  options,
  label,
  placeholder = "All",
  allLabel = "All",
  value,
  onChange,
}: DataTableStatusFilterProps<M>) {
  const { table } = useDataTableContext()
  const column = table.getColumn(columnId)

  if (mode === "single") {
    const singleValue = value as string | undefined
    const singleOnChange = onChange as (v: string | undefined) => void

    const clear = () => {
      singleOnChange(undefined)
      column?.setFilterValue(undefined)
    }

    const select = (next: string) => {
      singleOnChange(next)
      column?.setFilterValue(next)
    }

    const activeLabel = options.find((o) => o.value === singleValue)?.label

    return (
      <div className="flex items-center gap-1">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="h-8 w-full sm:w-auto" aria-label={label}>
              {label && <span className="text-muted-foreground">{label}:</span>}
              <span className="ml-1">{activeLabel ?? placeholder}</span>
              <ChevronDown className="ml-1 size-3.5 opacity-50" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" className="w-48">
            <DropdownMenuCheckboxItem checked={singleValue === undefined} onCheckedChange={clear}>
              {allLabel}
            </DropdownMenuCheckboxItem>
            <DropdownMenuSeparator />
            {options.map((opt) => (
              <DropdownMenuCheckboxItem
                key={opt.value}
                checked={singleValue === opt.value}
                onCheckedChange={() => select(opt.value)}
              >
                {opt.label}
              </DropdownMenuCheckboxItem>
            ))}
            {singleValue !== undefined && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuCheckboxItem
                  checked={false}
                  onCheckedChange={clear}
                  className="text-muted-foreground"
                >
                  Clear filter
                </DropdownMenuCheckboxItem>
              </>
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    )
  }

  const multiValue = value as string[]
  const multiOnChange = onChange as (v: string[]) => void

  const toggle = (optValue: string) => {
    const next = multiValue.includes(optValue)
      ? multiValue.filter((v) => v !== optValue)
      : [...multiValue, optValue]
    multiOnChange(next)
    column?.setFilterValue(next.length > 0 ? next : undefined)
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="h-8 w-full sm:w-auto" aria-label={label}>
          {label ?? placeholder}
          {multiValue.length > 0 && (
            <Badge variant="secondary" className="ml-1.5 rounded-sm px-1 font-normal">
              {multiValue.length}
            </Badge>
          )}
          <ChevronDown className="ml-1 size-3.5 opacity-50" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-48">
        {options.map((opt) => (
          <DropdownMenuCheckboxItem
            key={opt.value}
            checked={multiValue.includes(opt.value)}
            onCheckedChange={() => toggle(opt.value)}
          >
            {opt.label}
          </DropdownMenuCheckboxItem>
        ))}
        {multiValue.length > 0 && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuCheckboxItem
              checked={false}
              onCheckedChange={() => {
                multiOnChange([])
                column?.setFilterValue(undefined)
              }}
              className="text-muted-foreground"
            >
              Clear filter
            </DropdownMenuCheckboxItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

"use client"

import { useDataTableContext } from "@/components/data-table/core/context"
import { Button } from "@/components/ui/button"
import { Download, Loader2 } from "lucide-react"
import { useState } from "react"

type DataTableExportProps =
  | { mode: "client"; filename?: string }
  | { mode: "server"; onExport: () => Promise<Blob | string>; filename?: string }

function triggerDownload(content: Blob | string, filename: string) {
  const blob = typeof content === "string" ? new Blob([content], { type: "text/csv" }) : content
  const url = URL.createObjectURL(blob)
  const a = document.createElement("a")
  a.href = url
  a.download = filename
  a.click()
  URL.revokeObjectURL(url)
}

function buildCsv(headers: string[], rows: string[][]): string {
  const escape = (v: string) => (v.includes(",") || v.includes('"') || v.includes("\n") ? `"${v.replace(/"/g, '""')}"` : v)
  return [headers, ...rows].map((row) => row.map(escape).join(",")).join("\n")
}

export function DataTableExport(props: DataTableExportProps) {
  const { table } = useDataTableContext()
  const [loading, setLoading] = useState(false)
  const filename = `${props.filename ?? "export"}.csv`

  const handleClient = () => {
    const visibleColumns = table
      .getVisibleLeafColumns()
      .filter((col) => !(col.columnDef.meta as { isUtilityColumn?: boolean } | undefined)?.isUtilityColumn)

    const headers = visibleColumns.map((col) => {
      const header = col.columnDef.header
      return typeof header === "string" ? header : col.id
    })

    const rows = table.getRowModel().rows.map((row) =>
      visibleColumns.map((col) => {
        const value = row.getValue(col.id)
        return value == null ? "" : String(value)
      }),
    )

    triggerDownload(buildCsv(headers, rows), filename)
  }

  const handleServer = async () => {
    if (props.mode !== "server") return
    setLoading(true)
    try {
      const result = await props.onExport()
      triggerDownload(result, filename)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Button
      variant="outline"
      size="sm"
      className="h-8"
      disabled={loading}
